// ===============================
// TICKER ITERATION ENABLED
// ===============================

// Flag explícito
pm.environment.set("TICKER_ITERATION_ENABLED", "true");

// Soporte Runner / Newman
let ticker =
    pm.iterationData.get("TICKER_QUERY") ||
    pm.environment.get("TICKER_QUERY");

if (!ticker) {
    throw new Error("TICKER_QUERY no definido para carpeta con iteración");
}

pm.environment.set("TICKER_QUERY", ticker);

console.log(`▶ [${pm.info.folderName}] Ejecutando con ticker: ${ticker}`);

// ============================================================
// LOOKUP: SHORT_NAME via tradable-securities
// ============================================================
(function () {
    const pepperUrl  = pm.environment.get("PEPPER_LOCATION");
    const ticker     = pm.environment.get("TICKER_QUERY");
    const today      = new Date().toISOString().split("T")[0];
    const authHeader = pm.environment.get("AUTH_BASIC_HEADER");

    if (!authHeader) { throw new Error("AUTH_BASIC_HEADER no definido"); }

    pm.environment.set("VALUATION_DATE", today);

    pm.sendRequest({
        url: `${pepperUrl}/tradable-securities?query=${ticker}&tradeDate=${today}`,
        method: 'GET',
        header: {
            "Accept": "application/vnd.mercap.tradable-security+json;version=1.0.1",
            "Authorization": authHeader
        }
    }, function (err, res) {
        if (err) { throw new Error("Error en tradable-securities: " + err); }
        const items = res.json().items || [];
        const bond  = items.find(i => i.security && i.security.type === 'Bond');
        if (!bond) { throw new Error(`❌ No se encontró Bond para ${ticker}`); }
        pm.environment.set("SHORT_NAME", bond.security.shortName);
        console.log(`🔎 SHORT_NAME: ${bond.security.shortName}`);
    });
}());

const jsonData = pm.response.json();

// Verifica que la respuesta sea correcta
pm.test("Response is received", function () {
    pm.expect(pm.response).to.be.ok;
    console.log("Response received successfully.");
});

// Verifica que el status code sea 200
pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
    console.log("Status code is 200.");
});

// Verifica el Content-Type de la respuesta
pm.test("Media-Type is correct", function () {
    pm.response.to.have.header("Content-Type", "application/json");
    console.log("Content-Type header is correct.");
});

// Obtiene la respuesta en formato JSON
const response = pm.response.json();

// Verifica que el resultado sea un array no vacío
pm.test("Result is a non-empty array", function () {
    pm.expect(response.result).to.be.an('array').that.is.not.empty;
    console.log("Result is a non-empty array.");
});

// Verifica las propiedades de cada flujo de caja
pm.test("Each cashflow has correct properties", function () {
    response.result.forEach(item => {
        pm.expect(item).to.have.property('cashflow').that.is.an('array').that.is.not.empty;

        item.cashflow.forEach(cashflow => {
            pm.expect(cashflow).to.be.an('object').with.all.keys(
                'dueDate', 
                'amortizationToPay', 
                'interestToPayInIssueUnit', 
                'coupon', 
                'interestToPay', 
                'amortizationToPayInIssueUnit'
            );

            // Verifica que dueDate sea una fecha válida en formato YYYY-MM-DD
            pm.expect(cashflow.dueDate).to.match(/^\d{4}-\d{2}-\d{2}$/);

            // Verifica que coupon sea un número entero positivo
            pm.expect(cashflow.coupon).to.be.a('number').and.to.be.above(0);

            // Verifica que todas las propiedades monetarias tengan la estructura correcta
            const monetaryProps = [
                'amortizationToPay',
                'interestToPayInIssueUnit',
                'interestToPay',
                'amortizationToPayInIssueUnit'
            ];

            monetaryProps.forEach(prop => {
                pm.expect(cashflow[prop]).to.be.an('object').with.all.keys('unit', 'amount');
                pm.expect(cashflow[prop].unit).to.be.a('string').and.to.match(/^https?:\/\/[\w.-]+\/currencies\/[\w-]+$/);
                pm.expect(cashflow[prop].amount).to.be.a('number').and.to.be.at.least(0);
            });
        });
    });
    console.log("Each cashflow has the expected properties.");
});

// Verifica que los valores de "coupon" sean incrementales en 1

pm.test("Verify that coupon value is incremental by 1", function () {
    const result = pm.response.json().result[0].cashflow;

    result.forEach((coupon, index) => {
        if (index > 0) {
            pm.expect(coupon.coupon).to.equal(result[index - 1].coupon + 1);
        }
    });
    console.log("Coupon values are incremental by 1.");
});


// Verifica que todos los dueDate estén en orden ascendente para cada cashflow
pm.test("Due dates are in ascending order", function () {
    response.result.forEach(item => {
        const dates = item.cashflow.map(cashflow => new Date(cashflow.dueDate));
        for (let i = 1; i < dates.length; i++) {
            pm.expect(dates[i]).to.be.at.least(dates[i - 1]);
        }
    });
    console.log("Due dates are in ascending order for each cashflow.");
});

const expectedBondLink = pm.environment.get("BOND_INSTRUMENT_URL");

// Verifica que el link de bond coincida con la URL esperada
pm.test("Bond link is correct", function () {

    // Obtiene el valor de bond de la respuesta
    const bondLink = jsonData.result[0].bond;

    // Verifica que el link coincida con el esperado
    pm.expect(bondLink).to.equal(expectedBondLink);
    console.log("The bond link is correct:", bondLink);
});

const response = pm.response.json();
const regexDate = /^\d{4}-\d{2}-\d{2}$/;
const date = pm.environment.get("date");
const futureDate = pm.environment.get("futureDate");
pm.environment.set("SELF_URL", response.links.self);


pm.test("Los headers requeridos están presentes y son correctos", function () {
  const reqHeaders = pm.request.headers;
  const errores = [];

  const accept = reqHeaders.get("Content-Type");
  if (accept !== "application/vnd.mercap.bond-without-coupons+json;version=1.0.0") {
    errores.push(`Header Accept incorrecto: '${accept}'`);
  }

  const authorization = reqHeaders.get("Authorization");
  if (!authorization) {
    errores.push("Header Authorization faltante");
  }

  if (errores.length > 0) {
    throw new Error(`Problemas en los headers: ${errores.join(", ")}`);
  }
});

pm.test("El código de respuesta debe ser 201", function () {
  pm.response.to.have.status(201);
});

pm.test("La respuesta no debe estar vacía", function () {
  if (!response || Object.keys(response).length === 0) {
    throw new Error("Respuesta vacía: no se recibieron datos");
  }
});

pm.test("Todos los atributos requeridos deben estar presentes", function () {
  const requiredFields = [
    "shortName",
    "name",
    "issue.issueDate",
    "maturityDate",
    "issue.debtType",
    "issue.issueCountry",
    "issue.issuer",
    "issue.law",
    "issue.faceValueAmount",
    "couponPayment.offsetDays",
    "couponPayment.movementPolicy",
    "couponPayment.calendar",
    "couponPayment.keepInMonth"
  ];

  const faltantes = requiredFields.filter(path => {
    const parts = path.split(".");
    let value = response;
    for (const p of parts) {
      if (!value || !value.hasOwnProperty(p)) {
        return true;
      }
      value = value[p];
    }
    return false;
  });

  if (faltantes.length > 0) {
    throw new Error(`Faltan los siguientes atributos: ${faltantes.join(", ")}`);
  }
});

pm.test("No debe haber atributos con valores vacíos (excepto embeddedOptions)", function () {
  const vacios = [];

  const checkEmpty = (path) => {
    const parts = path.split(".");
    let value = response;
    for (const p of parts) {
      if (value && value.hasOwnProperty(p)) {
        value = value[p];
      } else {
        value = undefined;
        break;
      }
    }
    if (value === null || value === "" || value === undefined) {
      vacios.push(path);
    }
  };

  [
    "shortName",
    "name",
    "issue.issueDate",
    "maturityDate",
    "issue.debtType",
    "issue.issueCountry",
    "issue.issuer",
    "issue.law",
    "issue.faceValueAmount",
    "couponPayment.offsetDays",
    "couponPayment.movementPolicy",
    "couponPayment.calendar",
    "couponPayment.keepInMonth"
  ].forEach(checkEmpty);

  if (vacios.length > 0) {
    throw new Error(`Los siguientes atributos están vacíos: ${vacios.join(", ")}`);
  }
});

pm.test("El atributo embeddedOptions debe estar vacío", function () {
    pm.expect(response.embeddedOptions).to.be.an('array').that.is.empty;
});

pm.test("Cada atributo debe tener el formato correcto", function () {
  const erroresFormato = [];

  if (typeof response.shortName !== "string") erroresFormato.push("shortName debe ser string");
  if (typeof response.name !== "string") erroresFormato.push("name debe ser string");

  if (!regexDate.test(response.issue.issueDate)) erroresFormato.push("issueDate debe tener formato YYYY-MM-DD");
  if (!regexDate.test(response.maturityDate)) erroresFormato.push("maturityDate debe tener formato YYYY-MM-DD");

  if (typeof response.issue.debtType !== "string") erroresFormato.push("debtType debe ser string (URI)");
  if (typeof response.issue.issueCountry !== "string") erroresFormato.push("issueCountry debe ser string (URI)");
  if (typeof response.issue.issuer !== "string") erroresFormato.push("issuer debe ser string (URI)");
  if (typeof response.issue.law !== "string") erroresFormato.push("law debe ser string (URI)");

  if (typeof response.issue.faceValueAmount !== "number") erroresFormato.push("faceValueAmount debe ser number");

  if (!Number.isInteger(response.couponPayment.offsetDays)) erroresFormato.push("offsetDays debe ser integer");
  if (response.couponPayment.movementPolicy !== "next-working-day") erroresFormato.push("movementPolicy debe ser 'next-working-day'");
  if (typeof response.couponPayment.calendar !== "string") erroresFormato.push("calendar debe ser string (URI)");
  if (typeof response.couponPayment.keepInMonth !== "boolean") erroresFormato.push("keepInMonth debe ser boolean");

  if (erroresFormato.length > 0) {
    throw new Error(`Errores de formato/tipo: ${erroresFormato.join(", ")}`);
  }
});

pm.test("Debe existir objeto links con atributos self y deactivate", function () {
    pm.expect(response.links).to.have.property("self");
    pm.expect(response.links).to.have.property("deactivate");
});

pm.test("El atributo shortName debe ser '0AJWR6'", function () {
    pm.expect(response.shortName).to.eql("0AJWR6");
});

pm.test("El atributo name debe ser 'CRI VIRGO COMPANHIA DE SECURITIZACAO 2028 BRL 6.9809% (21J0001207)'", function () {
    pm.expect(response.name).to.eql("CRI VIRGO COMPANHIA DE SECURITIZACAO 2028 BRL 6.9809% (21J0001207)");
});

pm.test("El atributo issueDate debe ser " + date, function () {
    pm.expect(response.issue.issueDate).to.eql(date);
});

pm.test("El atributo maturityDate debe ser " + futureDate, function () {
    pm.expect(response.maturityDate).to.eql(futureDate);
});

pm.test("El atributo dayCountBasis.type debe ser 'business-day-252'", function () {
    pm.expect(response.issue.dayCountBasis.type).to.eql("business-day-252");
});

pm.test("El atributo cashflowUnits.type debe ser 'paid-in-issue-currency'", function () {
    pm.expect(response.issue.cashflowUnits.type).to.eql("paid-in-issue-currency");
});

pm.test("La respuesta contiene exactamente 6 cupones", function () {
    pm.expect(response).to.have.property("coupons");
    pm.expect(response.coupons).to.be.an("array");
    pm.expect(response.coupons.length).to.eql(6);
});

const date = new Date().toLocaleDateString('sv');
pm.environment.set("date", date);

const futureDate =  new Date(date);
futureDate.setFullYear(futureDate.getFullYear() + 1);


const firstCouponPayment = new Date(date);
firstCouponPayment.setMonth(firstCouponPayment.getMonth() + 3);
pm.environment.set("firstCouponPayment", firstCouponPayment.toLocaleDateString('sv'));

pm.environment.set("shortName", "0AJWR6");
pm.environment.set("name", "CRI VIRGO COMPANHIA DE SECURITIZACAO 2028 BRL 6.9809% (21J0001207)");

const calendar = pm.environment.get("holidays-location")

//logica para evitar dias no habiles

const queryRequest = {
    url: calendar + "/move-forward",
    method: 'QUERY',
    header: {
            'Accept': 'application/vnd.mercap.date-movement-result+json;version=1',
            'Content-Type': 'application/vnd.mercap.date-movement+json;version=1.0.0',
            'Authorization': 'Bearer ' + pm.environment.get("AUTHENTICATION_BEARER"),
    },
    body: JSON.stringify({
        "duration": "P1D",
        "startingDates": [
            futureDate.toLocaleDateString('sv')
        ]
    })
};

pm.sendRequest(queryRequest, (error, queryRequest) => {
    if (error) {
        console.error(error);
        return;
    }

    pm.environment.set("futureDate", queryRequest.json()[0].endDate);

});

