        "periodicity": "P6M",
        "type": "fixed",
        "yearlyRatePercentage": 8.5
    },
    "amortization": {
        "type": "bullet"
    }
}


let rq = {
    url: pm.environment.get("PEPPER_LOCATION") + "/brasil/bonds",
    method: 'POST',
    header: {
        'Authorization': "Bearer " + pm.environment.get("AUTHENTICATION_BEARER"),
        'Content-Type': "application/vnd.mercap.bond-without-coupons+json;version=1.0.0",
        'Accept': "application/vnd.mercap.bond+json;version=1.0.0"
    },
    body: {
            mode: 'raw',                          
            raw: JSON.stringify(requestBody)      
        }
};

pm.sendRequest(rq, function (err, resp) {

    if (err) {
        console.error(err);
        return;
    }
    let body = resp.json().links.self

    if (pm.environment.get("PEPPER_LOCATION").includes("localhost")){
        console.log( body.replace("qa-bonds", "localhost"))
        pm.environment.set("bond_test", body.replace("qa-bonds", "localhost"));
    }else{
        pm.environment.set("bond_test", body);
    }
});

const jsonData = pm.response.json();
const fromDate = pm.environment.get("pastDate");
const toDate = pm.environment.get("futureDate");
const issueCurrency = pm.environment.get("issuerCurrency");

pm.test("El código de respuesta debe ser 200", function () {
  pm.response.to.have.status(200);
});

pm.test("La respuesta contien las propiedades principales esperadas", function () {
    pm.expect(jsonData).to.have.property("issueUnit");
    pm.expect(jsonData).to.have.property("paymentCurrency");
    pm.expect(jsonData).to.have.property("flows");
    pm.expect(jsonData).to.have.property("links");
});

pm.test("'flows' es un array no vacío.", function () {
    pm.expect(jsonData.flows).to.be.an("array").that.is.not.empty;
});

pm.test("Cada elemento en 'flows' tiene propiedades requeridas", function () {
    jsonData.flows.forEach((flow, index) => {
        pm.expect(flow, `flow[${index}]`).to.have.property("coupon");
        pm.expect(flow, `flow[${index}]`).to.have.property("paymentDate");
        pm.expect(flow, `flow[${index}]`).to.have.property("interestToPay");
        pm.expect(flow, `flow[${index}]`).to.have.property("amortizationToPay");
        pm.expect(flow, `flow[${index}]`).to.have.property("residualValue");
    });
});

pm.test("Las propiedades en 'flows' tienen tipos correctos.", function () {
    const datePattern = /^\d{4}-\d{2}-\d{2}$/;

    jsonData.flows.forEach((flow, index) => {
        pm.expect(flow.coupon,             `flow[${index}].coupon`).to.be.a("number");
        pm.expect(flow.paymentDate,        `flow[${index}].paymentDate`).to.match(datePattern);
        pm.expect(flow.interestToPay,      `flow[${index}].interestToPay`).to.be.a("number");
        pm.expect(flow.amortizationToPay,  `flow[${index}].amortizationToPay`).to.be.a("number");
        pm.expect(flow.residualValue,      `flow[${index}].residualValue`).to.be.a("number");
    });
});

pm.test("'links' contiene 'self'", function () {
    pm.expect(jsonData.links).to.have.property("self");
    pm.expect(jsonData.links.self).to.be.a("string").that.is.not.empty;
});


pm.test("Cada elemento en 'flows' tiene propiedades requeridas", function () {
    jsonData.flows.forEach((flow, index) => {
        pm.expect(flow, `flow[${index}]`).to.have.property("residualValue");
    });
});

pm.test("All 'paymentDate' are between " + fromDate + " and " + toDate, function () {

    jsonData.flows.forEach((flow, index) => {
        const paymentDate = new Date(flow.paymentDate);
        const from = new Date(fromDate);
        const to = new Date(new Date(toDate).getTime() + 48 * 60 * 60 * 1000);

        pm.expect(
            paymentDate >= from && paymentDate <= to,
            `flow[${index}].paymentDate: ${flow.paymentDate} is out of range`
        ).to.be.true;
    });
});

pm.test("Validacion del calculo de intereses y amortizaciones", function () {
    const totalInterest = jsonData.flows.reduce((acc, flow) => acc + flow.interestToPay, 0);
    const totalAmortization = jsonData.flows.reduce((acc, flow) => acc + flow.amortizationToPay, 0);
    const combined = parseFloat((totalInterest + totalAmortization).toFixed(2));

    pm.expect(combined).to.eql(117);
});

pm.test("flows contiene la cantidad de cupones esperados", function () {
    const response = pm.response.json();
    pm.expect(response.flows).to.be.an("array").and.have.lengthOf(4);
});



